UPDATE scenario_steps SET message_content = '{"type":"flex","altText":"【15大特典への道 3/6】今日のミッション: キーコードを拡張機能に入力して自動化を1つ実行","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#D94A3D","paddingAll":"12px","contents":[{"type":"text","text":"15大特典への道 3/6","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"lg","paddingAll":"20px","contents":[{"type":"text","text":"昨日発行したキーコード、もう使ってみましたか？\n（まだの方は下のボタンから30秒で発行できます）","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"今日のミッション🎯\n▶ 発行したキーコードを拡張機能に入力して\n　自動化を1つ実行する","size":"sm","color":"#E8730C","wrap":true,"lineSpacing":"6px","weight":"bold"}]},{"type":"text","text":"クリアでもらえる特典","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px","margin":"md"},{"type":"box","layout":"horizontal","spacing":"sm","margin":"xs","contents":[{"type":"text","text":"📗","size":"sm","color":"#555555","wrap":true,"lineSpacing":"6px","flex":0},{"type":"text","text":"⑦ 外注化マニュアル 前編","size":"sm","color":"#555555","wrap":true,"lineSpacing":"6px","flex":1}]},{"type":"box","layout":"horizontal","spacing":"sm","margin":"xs","contents":[{"type":"text","text":"📗","size":"sm","color":"#555555","wrap":true,"lineSpacing":"6px","flex":0},{"type":"text","text":"⑧ 外注化マニュアル 後編","size":"sm","color":"#555555","wrap":true,"lineSpacing":"6px","flex":1}]},{"type":"box","layout":"vertical","spacing":"lg","margin":"md","contents":[{"type":"text","text":"自分の作業を\"人に任せる\"仕組み化の教科書。\n自動化と外注化で、稼働はさらに減らせます。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"受け取りはリッチメニューの「限定特典GET」をタップ👇","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]}]},"footer":{"type":"box","layout":"vertical","spacing":"md","contents":[{"type":"button","style":"primary","height":"sm","color":"#F68A1D","action":{"type":"message","label":"キーコード発行","text":"【リッチメニュー】キーコード発行"}}]}}}'
