-- Day4朝 FurimAutoの5段階
UPDATE scenario_steps SET message_content = '{"type":"flex","altText":"【FurimAutoが、リサーチを無料で配る理由】少しだけ、私たちの話をさせてください","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#2FA25B","paddingAll":"12px","contents":[{"type":"text","text":"FurimAutoの5段階","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"lg","paddingAll":"20px","contents":[{"type":"text","text":"FurimAutoが、リサーチを無料で配る理由","size":"lg","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"},{"type":"box","layout":"vertical","spacing":"lg","contents":[{"type":"text","text":"少しだけ、私たちの話をさせてください。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"FurimAutoは、現役のフリマ物販プレイヤーが作っている自動化ツールです。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"先に、身も蓋もない事実からお伝えします。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"フリマ物販に適したジャンルは、すでに世の中に出きっています。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"そして、いま売上が立っているアカウントこそが\"答え合わせの済んだ成功例\"です。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"だから、自分に合ったジャンルのトッププレイヤーを丸ごと真似する。それだけの、シンプルな事業です。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"オリジナリティは、むしろ邪魔になります。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"box","layout":"vertical","backgroundColor":"#F0FAF4","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"私たちが「今のフリマサイトでの成功の順番」だと確信しているのが、この5段階です。重要度も、①から順になっています。","size":"sm","color":"#2FA25B","wrap":true,"lineSpacing":"6px","weight":"bold"}]},{"type":"text","text":"① 何が売れるかを、事実で知る\n② 売れる商品を仕入れて、\n　いい写真・丁寧な情報を添えて出品する\n③ 毎日の作業を自動化して、売上を継続させる\n④ 販路を広げて、売上の上限を外す\n⑤ 増えた在庫を、事故なく回す","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"},{"type":"box","layout":"vertical","spacing":"lg","contents":[{"type":"text","text":"リサーチせずに仕入れた在庫は残ります。\n1つのサイトだけの運用には、天井が来ます。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"FurimAutoはこの5段階を、ぜんぶ1つの拡張機能に入れました。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"そして──\n入り口の①と②は、無料です。\n無料期間が終わっても、ずっと無料のままです。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"なぜそんなことをするのか。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"お金をお支払いいただいて活用してほしいのは、\n「商品が増えて、手が回らなくなった時」\nその時だけだからです。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"お客様のニーズは、百種百様です。\n商材・戦略・資金力・お使いのPCスペックまで、すべて異なります。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"そのニーズに応えられるように、FurimAutoは様々なサービス・機能を用意しています。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"\"人手が欲しくなった作業\"から、少しずつ任せてください。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"あなたが売れる。忙しくなる。\n「もう手作業には戻れない」と感じる。\nその時はじめて、次の段が目の前に現れる。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"FurimAutoは、そういう順番で使ってもらえるように作られています。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"さて、いまのあなたは、どの段にいますか？👇","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"image","url":"https://furimauto.com/line_images/roadmap_5steps.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"}]}}}'
WHERE scenario_id = '373c47a6-0197-419d-89ed-9e01dcc298c4' AND step_order = 8 AND message_type = 'flex';
