動画内で案内されるキーワードを送るだけです👇","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]}]},"footer":{"type":"box","layout":"vertical","spacing":"md","contents":[{"type":"button","style":"primary","height":"sm","color":"#FF0000","action":{"type":"uri","label":"無料期間を延長する！","uri":"https://youtu.be/jhaCPxgE_Sk"}}]}}}'
