UPDATE scenario_steps SET message_content = '{"type":"flex","altText":"おはようございます☀ 今日はまず、この1分動画だけ見てください","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 7｜1分で分かる全自動化","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://img.youtube.com/vi/uQjheVeAuww/maxresdefault.jpg","size":"full","aspectRatio":"16:9","aspectMode":"cover","action":{"type":"uri","uri":"https://www.youtube.com/watch?v=uQjheVeAuww"}},"body":{"type":"box","layout":"vertical","spacing":"lg","paddingAll":"20px","contents":[{"type":"text","text":"おはようございます☀","size":"lg","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"},{"type":"box","layout":"vertical","spacing":"lg","contents":[{"type":"text","text":"FurimAutoです。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"今日はまず、この動画だけ見てください。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"FurimAutoが目指す「全自動化」──新規出品と梱包発送以外の毎日の作業をぜんぶ任せる、という世界が1分で分かります。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"text","text":"長ったらしい説明はナシ！です🙅‍♀️\n使い方と他社ツールと比べた特徴を1分でまとめました!!","size":"xs","color":"#888888","wrap":true,"lineSpacing":"6px","margin":"md"}]},"footer":{"type":"box","layout":"vertical","spacing":"md","contents":[{"type":"button","style":"primary","height":"sm","color":"#FF0000","action":{"type":"uri","label":"YouTubeで見る","uri":"https://www.youtube.com/watch?v=uQjheVeAuww"}}]}}}'
