-- Day8朝 フリマSEO
UPDATE scenario_steps SET message_content = '{"type":"flex","altText":"【値下げと再出品は、何のためにやるのか】フリマサイト内のSEO対策の話です","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 8｜今日はここ：出品一覧ページ","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://furimauto.com/line_images/pages3_day2.png","size":"full","aspectRatio":"1:1","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"lg","paddingAll":"20px","contents":[{"type":"text","text":"値下げと再出品は、何のためにやるのか","size":"lg","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"},{"type":"box","layout":"vertical","spacing":"lg","contents":[{"type":"text","text":"先に言い切ります。\n値下げや再出品を\"するだけ\"で売れるわけではありません。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"でも、フリマサイトにははっきりした傾向があります。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"値下げ・再出品をした商品は検索結果の上位に戻り、閲覧数が増え、いいねが集まる。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"box","layout":"vertical","backgroundColor":"#FFF1EC","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"つまりこれは【フリマサイト内のSEO対策】です","size":"md","color":"#D94A3D","wrap":true,"lineSpacing":"6px","weight":"bold"}]},{"type":"image","url":"https://furimauto.com/line_images/seo_cycle.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"box","layout":"vertical","spacing":"lg","margin":"md","contents":[{"type":"text","text":"問題は、それを毎日手作業で続けられるか、です。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"FurimAutoなら、出品一覧ページの作業──値下げ・再出品・コメント管理・底値設定──を日時指定でまとめて予約でき、継続的に自動化できます。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"たとえば毎日の値段変更の予約の合間に、再出品を「朝10品・夜10品」で予約するだけで、1日20商品×30日、1ヶ月で約600品をフレッシュな商品ページとして回せます。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"今日はまず、自動値下げか自動再出品をどちらか1つだけ予約してみてください😊","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"}]}]},"footer":{"type":"box","layout":"vertical","spacing":"md","contents":[{"type":"button","style":"primary","height":"sm","color":"#FF0000","action":{"type":"uri","label":"予約のやり方を動画で見る","uri":"https://youtube.com/playlist?list=PLUhATsy78sfvUHMVmeQpKMyxATlHOCEeF&si=4ZT_HFKCIGcuHibG"}}]}}}'
WHERE scenario_id = '373c47a6-0197-419d-89ed-9e01dcc298c4' AND step_order = 14 AND message_type = 'flex';
-- Day9朝 価格ギャップ
UPDATE scenario_steps SET message_content = '{"type":"flex","altText":"【売る側は高く、買う側は安くのギャップがチャンス】自動いいね対応の話です","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 9｜今日はここ：お知らせページ","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://furimauto.com/line_images/pages3_day3.png","size":"full","aspectRatio":"1:1","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"lg","paddingAll":"20px","contents":[{"type":"text","text":"売る側は高く、買う側は安くのギャップがチャンス","size":"lg","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"},{"type":"box","layout":"vertical","spacing":"lg","contents":[{"type":"text","text":"物販の売上は、突き詰めるとこの綱引きです。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"売る側は、できるだけ高く売りたい。\n買う側は、できるだけ安く買いたい。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"この\"価格のギャップ\"をどれだけ上手に詰められるかが、フリマサイトで売上を伸ばすいちばん大事な施策です。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"そして、昨日お伝えしたSEOで閲覧といいねを集めた\"その先\"にあるのが【価格交渉】です。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"image","url":"https://furimauto.com/line_images/price_gap.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"box","layout":"vertical","spacing":"lg","margin":"md","contents":[{"type":"text","text":"いいねを付けた人は、「気になっているけど、あと一歩」の人。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"その人に向けてセールコメントを投稿し、こちらから能動的に\"交渉の場\"へお客さんを連れてくる──それがFurimAutoの【自動いいね対応】です。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"商品にいいねが付いたら、その人に向けたセールコメントを自動で投稿。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"買い手は少し安く買えて、あなたの在庫は現金に変わる。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"ギャップが縮まる瞬間を、体験してみてください😊","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"}]}]},"footer":{"type":"box","layout":"vertical","spacing":"md","contents":[{"type":"button","style":"primary","height":"sm","color":"#FF0000","action":{"type":"uri","label":"いいね対応の設定を見る","uri":"https://youtube.com/playlist?list=PLUhATsy78sfvUHMVmeQpKMyxATlHOCEeF&si=4ZT_HFKCIGcuHibG"}}]}}}'
WHERE scenario_id = '373c47a6-0197-419d-89ed-9e01dcc298c4' AND step_order = 15 AND message_type = 'flex';
-- Day10朝 取引メッセージの重荷
UPDATE scenario_steps SET message_content = '{"type":"flex","altText":"【売れるほど、忙しくなる問題】取引メッセージも自動化できます","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 10｜今日はここ：取引中ページ","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://furimauto.com/line_images/pages3_day4.png","size":"full","aspectRatio":"1:1","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"lg","paddingAll":"20px","contents":[{"type":"text","text":"売れるほど、忙しくなる問題","size":"lg","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"},{"type":"box","layout":"vertical","spacing":"lg","contents":[{"type":"text","text":"ここまでの自動化（値段変更・セールコメント施策・再出品）がうまく回り始めると、閲覧が増え、いいねが増え、月間の取引数も増えやすくなります。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"すると、次に重くなるのが──\n【取引メッセージのやり取り】です。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"購入のお礼、発送のご連絡、受取確認。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"メッセージ1通の処理は、スマホでコピペしても1分〜1分半。1つの取引で3〜4通やり取りするので、取引1件あたり4〜5分かかる計算です。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"image","url":"https://furimauto.com/line_images/msg_workload.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"box","layout":"vertical","spacing":"lg","margin":"md","contents":[{"type":"text","text":"取引が増えるほど、これが毎日積み上がっていきます。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"FurimAutoは、ここも自動化できます。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"取引メッセージを自動で送信。対応の早い出品者として購入者からの印象・評価にもつながります。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"売れるほど、ラクになる。\n全自動化の完成が、近づいてきました。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"}]}]},"footer":{"type":"box","layout":"vertical","spacing":"md","contents":[{"type":"button","style":"primary","height":"sm","color":"#FF0000","action":{"type":"uri","label":"取引自動化の設定を見る","uri":"https://youtube.com/playlist?list=PLUhATsy78sfvUHMVmeQpKMyxATlHOCEeF&si=4ZT_HFKCIGcuHibG"}}]}}}'
WHERE scenario_id = '373c47a6-0197-419d-89ed-9e01dcc298c4' AND step_order = 16 AND message_type = 'flex';
-- Day11朝 販路拡大
UPDATE scenario_steps SET message_content = '{"type":"flex","altText":"【1つのサイトで回ったら、次のステージへ】販路拡大はコピー出品で","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 11｜販路拡大","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"lg","paddingAll":"20px","contents":[{"type":"text","text":"1つのサイトで回ったら、次のステージへ","size":"lg","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"},{"type":"box","layout":"vertical","spacing":"lg","contents":[{"type":"text","text":"メルカリの運用が自動で回るようになったら、次にやるべきは【販路拡大】です。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"同じ商品でも、サイトが違えばお客さんも違う。出す場所を増やすだけで、売れるチャンスは単純に増えます。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"「でも、他のサイトに出品し直すのは面倒…」","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"FurimAutoなら、メルカリの商品データをもとに他のフリマサイトへ一気にコピー出品できます。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"image","url":"https://furimauto.com/line_images/copy_compare.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"box","layout":"horizontal","spacing":"sm","margin":"xs","contents":[{"type":"text","text":"・","size":"sm","color":"#555555","wrap":true,"lineSpacing":"6px","flex":0},{"type":"text","text":"手動のワンクリックコピーは、無料で使えます","size":"sm","color":"#555555","wrap":true,"lineSpacing":"6px","flex":1}]},{"type":"box","layout":"horizontal","spacing":"sm","margin":"xs","contents":[{"type":"text","text":"・","size":"sm","color":"#555555","wrap":true,"lineSpacing":"6px","flex":0},{"type":"text","text":"全自動の連続出品は、1品あたり10〜15円のチケット制（Day4で配った無料30枚も使えます）","size":"sm","color":"#555555","wrap":true,"lineSpacing":"6px","flex":1}]},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"販路拡大は、思っているよりずっと簡単です。\nまずは1品だけ、試しにコピーしてみてください😊","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"}]}]},"footer":{"type":"box","layout":"vertical","spacing":"md","contents":[{"type":"button","style":"primary","height":"sm","color":"#FF0000","action":{"type":"uri","label":"コピー出品のやり方を見る","uri":"https://youtube.com/playlist?list=PLUhATsy78sfvUHMVmeQpKMyxATlHOCEeF&si=4ZT_HFKCIGcuHibG"}}]}}}'
WHERE scenario_id = '373c47a6-0197-419d-89ed-9e01dcc298c4' AND step_order = 17 AND message_type = 'flex';
-- Day12朝 在庫管理
UPDATE scenario_steps SET message_content = '{"type":"flex","altText":"【最後の壁は、在庫管理】自動併売在庫管理で売り違いは構造的に起きません","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 12｜最後の壁は在庫管理","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"lg","paddingAll":"20px","contents":[{"type":"text","text":"最後の壁は、在庫管理","size":"lg","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"},{"type":"box","layout":"vertical","spacing":"lg","contents":[{"type":"text","text":"販路を広げると、最後にぶつかる壁があります。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"「メルカリで売れたのに、ラクマにも出したままだった…」","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"複数サイトでの在庫管理は地味で、そしてミスが命取りです。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"FurimAutoの【自動併売在庫管理】は、どこかのサイトで売れたら、他のサイトの同じ商品を自動で取り下げます。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"image","url":"https://furimauto.com/line_images/inventory_sync.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"box","layout":"vertical","spacing":"lg","margin":"md","contents":[{"type":"text","text":"売り違いの恐怖から解放されて、あなたがやるのは仕入れて、出品して、発送するだけ。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"リサーチ → 出品 → 自動化 → 販路拡大 → 在庫管理。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"},{"type":"text","text":"この2週間でご案内した階段をのぼり切ると、\"片手間でも、ちゃんと伸ばせる物販\"の形が完成します。","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px"}]},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"その形、このまま続けませんか？\n無料期間の終盤に、継続をご希望の方へのご案内をお送りします😊","size":"sm","color":"#333333","wrap":true,"lineSpacing":"6px","weight":"bold"}]}]},"footer":{"type":"box","layout":"vertical","spacing":"md","contents":[{"type":"button","style":"primary","height":"sm","color":"#FF0000","action":{"type":"uri","label":"在庫管理の始め方を見る","uri":"https://youtube.com/playlist?list=PLUhATsy78sfvUHMVmeQpKMyxATlHOCEeF&si=4ZT_HFKCIGcuHibG"}}]}}}'
WHERE scenario_id = '373c47a6-0197-419d-89ed-9e01dcc298c4' AND step_order = 18 AND message_type = 'flex';

