ineSpacing\":\"6px\"},{\"type\":\"text\",\"text\":\"最後にもう一度だけ、背中を押させてください👇\",\"size\":\"sm\",\"color\":\"#333333\",\"wrap\":true,\"lineSpacing\":\"6px\"}]}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"md\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"height\":\"sm\",\"color\":\"#FF0000\",\"action\":{\"type\":\"uri\",\"label\":\"無料期間を延長する！\",\"uri\":\"https://youtu.be/jhaCPxgE_Sk\"}},{\"type\":\"button\",\"style\":\"primary\",\"height\":\"sm\",\"color\":\"#D94A3D\",\"action\":{\"type\":\"uri\",\"label\":\"プラン診断をはじめる\",\"uri\":\"https://liff.line.me/1660804123-ZfTZnrBV\"}}]}}"}]}', '{"remaining_days_gte":1,"remaining_days_lte":1}', 1, '残1日: 本日で無料期間終了（Flex版）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
